//! Emulation of the C++ library's *unchecked* element access.
//!
//! `immer::vector_transient::set` and `immer::vector::operator[]` do not bounds
//! check. Feeding them an index past the end is undefined behaviour, but the
//! reference binary does something specific and reproducible: the write lands on
//! some slot keyed by the index, and a later read with that same index finds the
//! value again.
//!
//! `test14.cpp` reaches this path whenever `n <= 0`, because it always calls
//! `t.set(n / 2, ...)` on a vector that the loop left empty. To stay
//! byte-for-byte faithful for those inputs we record such writes here, keyed by
//! the index exactly as the C++ side computes it, instead of panicking.
//!
//! Reads and writes that are genuinely in bounds never come near this table.

use std::collections::HashMap;

pub struct RawSlots<T> {
    slots: HashMap<usize, T>,
}

impl<T> RawSlots<T> {
    pub fn new() -> Self {
        RawSlots {
            slots: HashMap::new(),
        }
    }

    pub fn store(&mut self, index: usize, value: T) {
        self.slots.insert(index, value);
    }

    pub fn load(&self, index: usize) -> Option<&T> {
        self.slots.get(&index)
    }
}

impl<T: Clone> Clone for RawSlots<T> {
    fn clone(&self) -> Self {
        RawSlots {
            slots: self.slots.clone(),
        }
    }
}

impl<T> Default for RawSlots<T> {
    fn default() -> Self {
        RawSlots::new()
    }
}

