//! `immer::vector` — an immutable vector with structural sharing.

use std::ops::Index;
use std::rc::Rc;

use super::raw_slots::RawSlots;
use super::trie::{self, Node, BITS, MASK, WIDTH};
use super::vector_transient::VectorTransient;

pub struct Vector<T> {
    pub(super) root: Rc<Node<T>>,
    pub(super) tail: Rc<Node<T>>,
    pub(super) size: usize,
    pub(super) shift: u32,
    pub(super) raw: RawSlots<T>,
}

impl<T: Clone> Vector<T> {
    pub fn new() -> Self {
        Vector {
            root: Node::empty_branch(),
            tail: Node::empty_leaf(),
            size: 0,
            shift: BITS,
            raw: RawSlots::new(),
        }
    }

    pub fn size(&self) -> usize {
        self.size
    }

    pub fn is_empty(&self) -> bool {
        self.size == 0
    }

    /// Append one element, leaving `self` untouched.
    pub fn push_back(&self, value: T) -> Vector<T> {
        let mut next = self.clone();
        next.push_back_mut(value);
        next
    }

    /// Replace the element at `index`, leaving `self` untouched.
    pub fn set(&self, index: usize, value: T) -> Vector<T> {
        let mut next = self.clone();
        next.set_mut(index, value);
        next
    }

    pub fn get(&self, index: usize) -> Option<&T> {
        if index >= self.size {
            return None;
        }
        Some(&self.leaf_for(index)[index & MASK])
    }

    /// Borrow a mutable view for batched edits. Nodes stay shared with `self`
    /// until the transient first writes to them.
    pub fn transient(&self) -> VectorTransient<T> {
        VectorTransient::from_persistent(self)
    }

    pub fn iter(&self) -> Iter<'_, T> {
        Iter {
            vector: self,
            index: 0,
        }
    }

    // --- internals shared with the transient -------------------------------

    pub(super) fn leaf_for(&self, index: usize) -> &Vec<T> {
        if index >= trie::tail_offset(self.size) {
            self.tail.leaf()
        } else {
            trie::leaf_for(&self.root, self.shift, index)
        }
    }

    pub(super) fn push_back_mut(&mut self, value: T) {
        let tail_len = self.size - trie::tail_offset(self.size);

        if tail_len < WIDTH {
            Rc::make_mut(&mut self.tail).leaf_mut().push(value);
            self.size += 1;
            return;
        }

        // Tail is full: move it into the tree and start a fresh one.
        let full = std::mem::replace(&mut self.tail, Rc::new(Node::Leaf(vec![value])));

        if (self.size >> BITS) > (1usize << self.shift) {
            // The tree is saturated; grow a level with the old root on the left.
            let grown = new_root(self.root.clone(), trie::new_path(self.shift, full));
            self.root = grown;
            self.shift += BITS;
        } else {
            trie::push_tail(&mut self.root, self.shift, full, self.size);
        }

        self.size += 1;
    }

    pub(super) fn set_mut(&mut self, index: usize, value: T) {
        if index >= self.size {
            // Unchecked in C++; see `raw_slots`.
            self.raw.store(index, value);
            return;
        }

        if index >= trie::tail_offset(self.size) {
            Rc::make_mut(&mut self.tail).leaf_mut()[index & MASK] = value;
        } else {
            trie::assoc(&mut self.root, self.shift, index, value);
        }
    }
}

fn new_root<T: Clone>(left: Rc<Node<T>>, right: Rc<Node<T>>) -> Rc<Node<T>> {
    Rc::new(Node::Branch(vec![left, right]))
}

impl<T: Clone> Clone for Vector<T> {
    fn clone(&self) -> Self {
        Vector {
            root: Rc::clone(&self.root),
            tail: Rc::clone(&self.tail),
            size: self.size,
            shift: self.shift,
            raw: self.raw.clone(),
        }
    }
}

impl<T: Clone> Default for Vector<T> {
    fn default() -> Self {
        Vector::new()
    }
}

/// Mirrors `operator[]`, which is unchecked in C++. In-bounds indices take the
/// normal path; an out-of-bounds index resolves against the recorded raw slots.
impl<T: Clone> Index<usize> for Vector<T> {
    type Output = T;

    fn index(&self, index: usize) -> &T {
        if index < self.size {
            return &self.leaf_for(index)[index & MASK];
        }
        match self.raw.load(index) {
            Some(value) => value,
            None => panic!(
                "read of index {} past end (size {}) with no recorded slot",
                index, self.size
            ),
        }
    }
}

pub struct Iter<'a, T> {
    vector: &'a Vector<T>,
    index: usize,
}

impl<'a, T: Clone> Iterator for Iter<'a, T> {
    type Item = &'a T;

    fn next(&mut self) -> Option<&'a T> {
        let item = self.vector.get(self.index)?;
        self.index += 1;
        Some(item)
    }
}

