//! Faithful `std::stoi` behaviour, including how a failure terminates the
//! process.
//!
//! `std::stoi` skips leading whitespace, accepts an optional sign, consumes the
//! longest run of base-10 digits and *ignores* whatever follows ("12abc" is 12).
//! With no digits at all it throws `std::invalid_argument`; outside `int` range
//! it throws `std::out_of_range`. Neither is caught in `test14.cpp`, so the
//! runtime prints a fixed diagnostic to stderr and aborts.

use std::process;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum StoiError {
    InvalidArgument,
    OutOfRange,
}

impl StoiError {
    fn exception_name(self) -> &'static str {
        match self {
            StoiError::InvalidArgument => "std::invalid_argument",
            StoiError::OutOfRange => "std::out_of_range",
        }
    }
}

fn is_space(byte: u8) -> bool {
    matches!(byte, b' ' | b'\t' | b'\n' | 0x0b | 0x0c | b'\r')
}

pub fn stoi(text: &str) -> Result<i32, StoiError> {
    let bytes = text.as_bytes();
    let mut pos = 0;

    while pos < bytes.len() && is_space(bytes[pos]) {
        pos += 1;
    }

    let negative = match bytes.get(pos) {
        Some(b'-') => {
            pos += 1;
            true
        }
        Some(b'+') => {
            pos += 1;
            false
        }
        _ => false,
    };

    let digits_start = pos;
    // Accumulate in i64 and clamp: the magnitude only has to be compared
    // against the int range, so saturating early is indistinguishable.
    let mut magnitude: i64 = 0;
    while pos < bytes.len() && bytes[pos].is_ascii_digit() {
        let digit = i64::from(bytes[pos] - b'0');
        magnitude = magnitude.saturating_mul(10).saturating_add(digit);
        pos += 1;
    }

    if pos == digits_start {
        return Err(StoiError::InvalidArgument);
    }

    let value = if negative { -magnitude } else { magnitude };
    if value < i64::from(i32::MIN) || value > i64::from(i32::MAX) {
        return Err(StoiError::OutOfRange);
    }
    Ok(value as i32)
}

/// Reproduce an uncaught-exception exit: the libstdc++ diagnostic on stderr,
/// then `abort` (SIGABRT, which shells report as exit status 134).
pub fn terminate_with(error: StoiError) -> ! {
    eprintln!(
        "terminate called after throwing an instance of '{}'",
        error.exception_name()
    );
    eprintln!("  what():  stoi");
    process::abort();
}

