//! Bit-partitioned vector trie: the shared backbone of `vector` and
//! `vector_transient`.
//!
//! The layout mirrors the one `immer::vector` uses: a tree of 32-way nodes
//! holding every element except the last partial block, plus a separate "tail"
//! leaf that absorbs appends so the common `push_back` case never walks the
//! tree.
//!
//! Sharing is done with `Rc`, and every mutating helper goes through
//! `Rc::make_mut`. That single choice gives both flavours their behaviour: a
//! persistent `vector` clones the handle first, so its nodes are shared and
//! `make_mut` copies the path (structural sharing); a transient owns its nodes
//! outright, so `make_mut` hands back the existing node and the write lands in
//! place.

use std::rc::Rc;

/// Bits of index consumed per tree level.
pub const BITS: u32 = 5;
/// Children per node.
pub const WIDTH: usize = 1 << BITS;
/// Mask selecting the index bits for one level.
pub const MASK: usize = WIDTH - 1;

pub enum Node<T> {
    Leaf(Vec<T>),
    Branch(Vec<Rc<Node<T>>>),
}

impl<T: Clone> Node<T> {
    pub fn empty_leaf() -> Rc<Node<T>> {
        Rc::new(Node::Leaf(Vec::new()))
    }

    pub fn empty_branch() -> Rc<Node<T>> {
        Rc::new(Node::Branch(Vec::new()))
    }

    pub fn leaf(&self) -> &Vec<T> {
        match self {
            Node::Leaf(items) => items,
            Node::Branch(_) => unreachable!("expected a leaf node"),
        }
    }

    pub fn leaf_mut(&mut self) -> &mut Vec<T> {
        match self {
            Node::Leaf(items) => items,
            Node::Branch(_) => unreachable!("expected a leaf node"),
        }
    }

    pub fn branch(&self) -> &Vec<Rc<Node<T>>> {
        match self {
            Node::Branch(children) => children,
            Node::Leaf(_) => unreachable!("expected a branch node"),
        }
    }

    pub fn branch_mut(&mut self) -> &mut Vec<Rc<Node<T>>> {
        match self {
            Node::Branch(children) => children,
            Node::Leaf(_) => unreachable!("expected a branch node"),
        }
    }
}

/// First index living in the tail rather than in the tree.
pub fn tail_offset(size: usize) -> usize {
    if size < WIDTH {
        0
    } else {
        ((size - 1) >> BITS) << BITS
    }
}

/// Wrap `node` in `level / BITS` fresh single-child branches so it sits at the
/// depth the tree currently expects.
pub fn new_path<T: Clone>(level: u32, node: Rc<Node<T>>) -> Rc<Node<T>> {
    if level == 0 {
        node
    } else {
        Rc::new(Node::Branch(vec![new_path(level - BITS, node)]))
    }
}

/// Graft a full tail leaf onto the rightmost edge of the tree.
///
/// `size` is the element count *before* the append, which is what makes
/// `(size - 1) >> level` name the slot the new leaf belongs in. Because
/// elements only ever arrive at the back, that slot is either the last existing
/// child (descend) or one past it (append).
pub fn push_tail<T: Clone>(node: &mut Rc<Node<T>>, level: u32, tail: Rc<Node<T>>, size: usize) {
    let slot = ((size - 1) >> level) & MASK;
    let children = Rc::make_mut(node).branch_mut();

    if level == BITS {
        debug_assert_eq!(slot, children.len(), "tail must land past the last leaf");
        children.push(tail);
    } else if slot < children.len() {
        push_tail(&mut children[slot], level - BITS, tail, size);
    } else {
        debug_assert_eq!(slot, children.len(), "subtree must land past the last child");
        children.push(new_path(level - BITS, tail));
    }
}

/// Overwrite the element at `index`, which must live in the tree (not the tail).
pub fn assoc<T: Clone>(node: &mut Rc<Node<T>>, level: u32, index: usize, value: T) {
    if level == 0 {
        Rc::make_mut(node).leaf_mut()[index & MASK] = value;
    } else {
        let slot = (index >> level) & MASK;
        assoc(
            &mut Rc::make_mut(node).branch_mut()[slot],
            level - BITS,
            index,
            value,
        );
    }
}

/// Walk the tree down to the leaf holding `index`.
pub fn leaf_for<T: Clone>(root: &Rc<Node<T>>, shift: u32, index: usize) -> &Vec<T> {
    let mut node = root;
    let mut level = shift;
    while level > 0 {
        node = &node.branch()[(index >> level) & MASK];
        level -= BITS;
    }
    node.leaf()
}

